-- Bank transfer: the classic ACID transaction
BEGIN;

  -- Debit source account
  UPDATE accounts
  SET balance = balance - 100
  WHERE id = 1;

  -- Verify the account didn't go negative (application-level consistency)
  -- In PostgreSQL you can use a CHECK constraint: balance >= 0
  -- Here we abort manually if violated
  DO $$
  BEGIN
    IF (SELECT balance FROM accounts WHERE id = 1) < 0 THEN
      RAISE EXCEPTION 'Insufficient funds';
    END IF;
  END $$;

  -- Credit destination account
  UPDATE accounts
  SET balance = balance + 100
  WHERE id = 2;

COMMIT;
-- If any statement raises an error, PostgreSQL automatically rolls back.
-- The EXCEPTION in the DO block triggers ROLLBACK, leaving both
-- accounts unchanged.

-- Lock a row for the duration of a transaction (Repeatable Read semantics)
-- Prevents another transaction from modifying user 42 until we commit
BEGIN;
  SELECT * FROM users WHERE id = 42 FOR UPDATE;
  UPDATE users SET email = 'new@example.com' WHERE id = 42;
COMMIT;

-- NORMALIZATION: fixing common violations

-- BAD (1NF violation): array in a cell
CREATE TABLE orders_bad (
  id      SERIAL PRIMARY KEY,
  items   TEXT   -- 'pen,ruler,glue'
);
-- GOOD (1NF): separate table
CREATE TABLE order_items (
  order_id  INT REFERENCES orders(id),
  item_name TEXT NOT NULL,
  PRIMARY KEY (order_id, item_name)
);

-- BAD (2NF violation): partial key dependency
CREATE TABLE order_items_bad (
  order_id    INT,
  product_id  INT,
  product_name TEXT, -- depends only on product_id
  quantity    INT,
  PRIMARY KEY (order_id, product_id)
);
-- GOOD (2NF): extract products table
CREATE TABLE products (
  id   SERIAL PRIMARY KEY,
  name TEXT NOT NULL
);
-- order_items references products(id)

-- BAD (3NF violation): transitive dependency
CREATE TABLE employees_bad (
  id        SERIAL PRIMARY KEY,
  dept_id   INT,
  dept_name TEXT  -- depends on dept_id, not directly on id
);
-- GOOD (3NF): extract departments table
CREATE TABLE departments (
  id   SERIAL PRIMARY KEY,
  name TEXT NOT NULL
);
CREATE TABLE employees (
  id      SERIAL PRIMARY KEY,
  dept_id INT REFERENCES departments(id)
);

-- Isolation level example
BEGIN;
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
  -- Both transactions will be checked for serializability conflicts
  SELECT * FROM accounts WHERE balance > 1000;
  UPDATE accounts SET balance = balance + 50 WHERE id = 99;
COMMIT; -- May raise: ERROR: could not serialize access due to read/write dependencies
